#!/usr/bin/env bash
set -euo pipefail
command -v node >/dev/null 2>&1 || { echo 'Node.js is required.' >&2; exit 1; }
node <<'AF_SIMPLIFY_HEADER_NODE'
'use strict';
const fs=require('node:fs'),path=require('node:path');const root=process.cwd(),files={"src/app/simulations/all/page.tsx": "'use client';\nimport { useState } from 'react';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\nimport { topics, normalize } from '@/lib/explorer/catalog';\nconst subjects=['All','Physics','Chemistry','Mathematics','Geophysics'];\nexport default function AllSimulationsPage(){\n const [subject,setSubject]=useState('All'),[search,setSearch]=useState('');\n const query=normalize(search);\n const visible=topics.filter(t=>(subject==='All'||t.subject===subject)&&(!query||normalize([t.title,t.description,...t.aliases].join(' ')).includes(query)));\n return <div style={{background:'#f1f5f9',color:'#111827',minHeight:'100vh',colorScheme:'light'}}><AppHeader/><main className=\"af-explorer mx-auto min-w-0 max-w-7xl px-4 py-8 sm:px-6 sm:py-12\">\n  <p className=\"text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"mt-2 text-3xl font-semibold\">All simulations &amp; activities</h1><p className=\"mt-3 max-w-2xl text-sm leading-7 text-gray-700\">Browse {topics.length} existing activities across Physics, Chemistry, Mathematics and Geophysics. Open an activity to use its controls, or choose Try AI for guided explanations.</p>\n  <div className=\"mt-6 min-w-0\"><label htmlFor=\"simulation-search\" className=\"mb-2 block text-sm font-medium\">Find an activity</label><input id=\"simulation-search\" type=\"search\" value={search} onChange={e=>setSearch(e.target.value)} placeholder=\"Search by topic or concept\" className=\"min-h-11 w-full min-w-0 rounded-xl border border-gray-300 bg-white px-4 py-3 text-base text-gray-900 placeholder:text-gray-600\"/></div>\n  <div className=\"mt-4 flex max-w-full gap-2 overflow-x-auto pb-2\" aria-label=\"Filter activities by subject\">{subjects.map(s=><button key={s} onClick={()=>setSubject(s)} aria-pressed={subject===s} className={`min-h-11 shrink-0 rounded-full border px-4 py-2 text-sm font-medium ${subject===s?'border-indigo-700 bg-indigo-700 text-white':'border-gray-300 bg-white text-gray-700'}`}>{s}</button>)}</div>\n  <p role=\"status\" className=\"my-4 text-xs text-gray-700\">{visible.length} activities</p>\n  <div className=\"grid min-w-0 gap-4 sm:grid-cols-2 lg:grid-cols-3\">{visible.map(t=><article key={t.id} className=\"flex min-w-0 flex-col rounded-2xl border border-gray-200 bg-white p-5\"><p className=\"text-xs font-semibold text-indigo-700\">{t.subject}</p><h2 className=\"mt-2 text-lg font-semibold\"><Link href={t.route} className=\"hover:text-indigo-800 hover:underline\">{t.title}</Link></h2><p className=\"mb-5 mt-2 flex-1 text-sm leading-7 text-gray-700\">{t.description}</p>{t.protected&&<p className=\"mb-3 text-xs text-amber-900\">Student login required by the existing Minitab tool.</p>}<Link href={t.route} className=\"inline-flex min-h-11 items-center justify-center rounded-xl border border-indigo-200 bg-indigo-50 px-4 py-2 text-sm font-semibold text-indigo-900\">Open activity →</Link></article>)}</div>\n  {!visible.length&&<p className=\"rounded-xl border border-gray-200 bg-white p-6 text-sm text-gray-700\">No matching activities. Try another search or choose All.</p>}\n </main></div>;\n}\n", "src/app/explore/page.tsx": "import { AppHeader } from '@/components/layout/AppHeader';\nimport { PromptBar } from '@/components/ai/PromptBar';\nimport { topics } from '@/lib/explorer/catalog';\nexport const metadata={title:'Try AI | A-Factor STEM Studio'};\nexport default function ExplorePage(){return <div style={{background:'#f1f5f9',minHeight:'100vh',color:'#111827',colorScheme:'light'}}><AppHeader/><main className=\"af-explorer mx-auto min-w-0 max-w-6xl px-3 py-6 sm:px-6 sm:py-10\"><p className=\"text-xs font-semibold uppercase tracking-widest text-indigo-700\">A-Factor STEM Studio</p><h1 className=\"mt-2 text-3xl font-semibold\">Understand a STEM concept</h1><p className=\"mb-7 mt-3 max-w-2xl text-sm leading-7 text-gray-700\">Choose from {topics.length} existing topics to get a guided explanation, inspect a supported calculation and prepare a related simulation. This free demo uses rules and prepared content without a paid AI API.</p><PromptBar/></main></div>;}\n", "capstone/HEADER_MENU_UPDATE.md": "# Simplified header navigation\n\nRun `bash patch-simplify-header-menus.sh` from your project root, then restart `npm run dev`.\n\n- Simulations links directly to /simulations/all: the catalogue of all 58 registered activities, with subject filters and search.\n- Try AI links to /explore: the same guided explainer and supported-calculation workflow previously named Explore topics.\n- The separate Explore topics navigation entry is removed on desktop and mobile.\n- STEM Tutor, About and Student Login remain in the header.\n- The explainer stays below the header and existing mobile navigation behaviour is retained.\n\nThe original /simulations Physics directory is retained, so existing links continue to work. Chemistry, Mathematics and Geophysics remain discoverable through the all-activity catalogue. Existing student-login restrictions still apply to protected activities.\n\nTry AI is a navigation label, not a change of engine: the free demo continues to use rules, prepared explanations and selected calculations. General conversational problem solving would require a separate model integration. This patch does not enable paid API requests.\n\nChanged files are backed up before installation. The installer updates the header's relevant navigation entries while preserving other header customisations. TypeScript and production build checks were run; live browser visual testing remains unverified.\n"};
function stop(message){console.error('Patch stopped: '+message+' No application files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/lib/explorer/catalog.ts'))stop('Run from the root of the project with the all-topic explorer installed.');
let ts;try{ts=require(path.join(root,'node_modules/typescript'));}catch{stop('Run npm install for your existing dependencies first.');}
function safe(file){let cur=root;for(const part of file.split('/')){cur=path.join(cur,part);try{if(fs.lstatSync(cur).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
const file='src/components/layout/AppHeader.tsx';safe(file);if(!fs.existsSync(file))stop('Shared header not found.');let s=fs.readFileSync(file,'utf8');
function ast(){return ts.createSourceFile(file,s,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX);}
function walk(n,fn){fn(n);ts.forEachChild(n,c=>walk(c,fn));}
function apply(edits){for(const e of edits.sort((a,b)=>b.start-a.start))s=s.slice(0,e.start)+e.text+s.slice(e.end);}
// Remove just the redundant Explore topics item from the existing NAV array.
let edits=[];walk(ast(),n=>{if(!ts.isVariableDeclaration(n)||n.name.getText()!=='NAV'||!n.initializer||!ts.isArrayLiteralExpression(n.initializer))return;for(const e of n.initializer.elements){if(!ts.isObjectLiteralExpression(e))continue;const href=e.properties.find(p=>ts.isPropertyAssignment(p)&&p.name.getText().replace(/['"]/g,'')==='href');if(href&&ts.isStringLiteral(href.initializer)&&href.initializer.text==='/explore'){let end=e.end;if(s[end]===',')end++;edits.push({start:e.getStart(),end,text:''});}}});apply(edits);
// Replace the subject dropdowns with one direct catalogue link in each layout.
s=s.replace(/<SimulationsMenu\s*\/>/g,'<Link href="/simulations/all" className="rounded-lg px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 hover:text-indigo-700">Simulations</Link>');
s=s.replace(/<SimulationsMobileMenu\s+onNavigate=\{\(\)\s*=>\s*setOpen\(false\)\}\s*\/>/g,'<Link href="/simulations/all" onClick={() => setOpen(false)} className="block min-h-11 rounded-lg px-3 py-3 text-sm font-medium text-gray-700 hover:bg-gray-100">Simulations</Link>');
edits=[];for(const n of ast().statements)if(ts.isImportDeclaration(n)&&n.moduleSpecifier.text==='@/components/layout/SimulationsMenu'){const binding=n.importClause?.namedBindings;if(binding&&ts.isNamedImports(binding)){const keep=binding.elements.filter(e=>!['SimulationsMenu','SimulationsMobileMenu'].includes(e.name.text));if(!keep.length)edits.push({start:n.getStart(),end:n.end,text:''});else edits.push({start:binding.getStart(),end:binding.end,text:'{ '+keep.map(e=>e.getText()).join(', ')+' }'});}}apply(edits);
// Merge the CTA and explorer link without changing unrelated links or menu items.
edits=[];let simulationLinks=0,aiLinks=0;
walk(ast(),n=>{if(!ts.isJsxElement(n)||n.openingElement.tagName.getText()!=='Link')return;const text=n.children.filter(ts.isJsxText).map(c=>c.text).join(' ').trim().replace(/\s+/g,' ');const href=n.openingElement.attributes.properties.find(a=>ts.isJsxAttribute(a)&&a.name.getText()==='href');if(!href?.initializer||!ts.isStringLiteral(href.initializer))return;
 if(text==='Explore topics'){edits.push({start:n.getStart(),end:n.end,text:''});return;}
 if(text==='Simulations'){simulationLinks++;edits.push({start:href.initializer.getStart(),end:href.initializer.end,text:'"/simulations/all"'});}
 if(/^Try\s+(now|AI)$/i.test(text)){aiLinks++;edits.push({start:href.initializer.getStart(),end:href.initializer.end,text:'"/explore"'});for(const c of n.children)if(ts.isJsxText(c)&&/Try\s+(now|AI)/i.test(c.text))edits.push({start:c.pos,end:c.end,text:c.text.replace(/Try\s+(now|AI)/i,'Try AI')});}
});if(simulationLinks!==2||aiLinks!==2)stop('Could not identify both desktop and mobile Simulations/AI links.');apply(edits);
s=s.replace('ml-2 rounded-lg bg-indigo-600','ml-2 inline-flex min-h-11 items-center rounded-lg bg-indigo-600').replace('block mt-2 rounded-lg bg-indigo-600 px-3 py-2','block mt-2 min-h-11 rounded-lg bg-indigo-600 px-3 py-3');files[file]=s;
for(const target of [...Object.keys(files),'.stem-tutor-backups'])safe(target);
const changed=Object.keys(files).filter(p=>!fs.existsSync(p)||fs.readFileSync(p,'utf8')!==files[p]);if(!changed.length){console.log('Simplified header is already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/header-menus-'),originals=new Map();
for(const p of changed){const original=fs.existsSync(p)?fs.readFileSync(p):null;originals.set(p,original);if(original!==null){const target=path.join(backup,p);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,original);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const p of changed){fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,files[p],'utf8');}}catch(error){for(const [p,original] of originals){if(original===null){if(fs.existsSync(p))fs.unlinkSync(p);}else fs.writeFileSync(p,original);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Header simplified: Simulations -> /simulations/all; Try AI -> /explore.');console.log('Backup: '+backup);console.log('Restart npm run dev and refresh your page.');
AF_SIMPLIFY_HEADER_NODE
